const OPTION_DEFINITIONS = [
  { flag: '--a', key: 'a', metavar: 'A', type: 'string' },
  { flag: '--b', key: 'b', metavar: 'B', type: 'string' },
  { flag: '--c', key: 'c', metavar: 'C', type: 'string' },
  { flag: '--d', key: 'd', metavar: 'D', type: 'string' },
  { flag: '--e', key: 'e', metavar: 'E', type: 'int' },
  { flag: '--f', key: 'f', metavar: 'F', type: 'int' },
];

const OPTION_BY_FLAG = Object.freeze(
  Object.fromEntries(OPTION_DEFINITIONS.map((definition) => [definition.flag, definition])),
);

const INTEGER_PATTERN = /^[+-]?\d+$/u;
const NEGATIVE_NUMBER_PATTERN = /^-\d+$/u;

function programNameFromArgv(argv) {
  return basename(argv[1] ?? 'test19.mjs');
}

function usageLine(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D --e E --f F`;
}

function helpText(programName) {
  const lines = [
    usageLine(programName),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    ...OPTION_DEFINITIONS.map((definition) => `  ${definition.flag} ${definition.metavar}`),
  ];

  return lines.join('\n');
}

function exitWithError(programName, message) {
  process.stderr.write(`${usageLine(programName)}\n`);
  process.stderr.write(`${programName}: error: ${message}\n`);
  process.exit(2);
}

function exitWithHelp(programName) {
  process.stdout.write(`${helpText(programName)}\n`);
  process.exit(0);
}

function looksLikeOption(token) {
  return token.startsWith('-') && !NEGATIVE_NUMBER_PATTERN.test(token);
}

function parseDecimalInteger(text) {
  const negative = text.startsWith('-');
  const startIndex = text.startsWith('-') || text.startsWith('+') ? 1 : 0;
  let value = 0n;

  for (let index = startIndex; index < text.length; index += 1) {
    value = (value * 10n) + BigInt(text.charCodeAt(index) - 0x30);
  }

  return negative ? -value : value;
}

function parseOptionValue(rawValue, definition, programName) {
  if (definition.type === 'string') {
    return rawValue;
  }

  if (!INTEGER_PATTERN.test(rawValue)) {
