export function parseArgumentsOrExit(argv) {
  const programName = programNameFromArgv(argv);
  const tokens = argv.slice(2);
  const values = Object.create(null);
  const extras = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '-h' || token === '--help') {
      exitWithHelp(programName);
    }

    if (token === '--') {
      extras.push(...tokens.slice(index + 1));
      break;
