    return String.fromCharCode(byte);
  }

  return `\\x${HEX_DIGITS[(byte >> 4) & 0x0f]}${HEX_DIGITS[byte & 0x0f]}`;
}

export function formatPythonBytes(bytes) {
  const quote = selectQuote(bytes);
  let formatted = `b${quote}`;

  for (const byte of bytes) {
    formatted += formatByte(byte, quote);
  }

  formatted += quote;
